<script>(() => { const modal=document.getElementById('admin-personnel-add-modal'); if(!modal)return; const buttons=[...modal.querySelectorAll('[data-personnel-mode]')], panels=[...modal.querySelectorAll('[data-personnel-panel]')]; const setMode=(mode)=>{buttons.forEach(b=>{const on=b.dataset.personnelMode===mode;b.classList.toggle('bg-white',on);b.classList.toggle('text-red-700',on);b.classList.toggle('shadow-sm',on);b.classList.toggle('text-slate-500',!on)});panels.forEach(p=>p.classList.toggle('hidden',p.dataset.personnelPanel!==mode));}; const close=()=>{modal.classList.add('hidden');document.body.classList.remove('overflow-hidden')}; document.querySelectorAll('[data-admin-panel="admin-personnel-add-modal"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setMode('manual');modal.classList.remove('hidden');document.body.classList.add('overflow-hidden')}));buttons.forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.personnelMode)));modal.querySelectorAll('[data-close-personnel-modal]').forEach(b=>b.addEventListener('click',close));modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.classList.contains('hidden'))close()});setMode('manual');})();</script>
